#!/usr/bin/env python3
"""Fail build/READY validation if the installed image decoders cannot decode real data."""
import base64
import io
from PIL import Image
import pi_heif

pi_heif.register_heif_opener()
HEIC = ''
with Image.open(io.BytesIO(base64.b64decode(HEIC))) as decoded:
    decoded.load()
    assert decoded.size == (320, 240)
with io.BytesIO() as buffer:
    Image.new("RGB", (2, 2), (80, 120, 160)).save(buffer, format="PNG")
    buffer.seek(0)
    with Image.open(buffer) as decoded:
        decoded.load()
        assert decoded.getpixel((0, 0)) == (80, 120, 160)
print("Pillow/pi-heif actual decode passed")
